package com.smritisathi.app.reminders;
import android.os.*;import android.graphics.Color;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;import java.util.*;
public class ReminderActivity extends BaseActivity {LinearLayout list;String id,token;@Override public void onCreate(Bundle b){super.onCreate(b);id=Session.id(this);token=Session.token(this);header("Today's Reminders");root.addView(UI.text(this,"Stay on track with your daily schedule"));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);load();}void load(){ApiClient.request("GET","/reminders/patient/"+id,token,null,(ok,d,e)->{list.removeAllViews();if(ok&&d.has("data")&&d.getAsJsonArray("data").size()>0){for(JsonElement x:d.getAsJsonArray("data"))add(x.getAsJsonObject());}else{addMock("💊 Take evening medication");addMock("💧 Drink some water");}});}void addMock(String s){TextView t=UI.card(this,s+"\nTap Done when completed.");list.addView(t);t.setOnClickListener(v->{t.setText(s+"\n✓ Done");});}void add(JsonObject r){String idr=r.has("_id")?r.get("_id").getAsString():"";TextView t=UI.card(this,(r.has("type")?r.get("type").getAsString().toUpperCase()+" — ":"")+r.get("title").getAsString()+"\n"+(r.has("scheduledTime")?r.get("scheduledTime").getAsString():"")+"\nStatus: "+(r.has("status")?r.get("status").getAsString():"pending"));list.addView(t);t.setOnClickListener(v->{if(!idr.isEmpty()){JsonObject b=new JsonObject();b.addProperty("status","done");ApiClient.request("PATCH","/reminders/"+idr+"/status",token,b,(ok,d,e)->{if(ok)t.setText(r.get("title").getAsString()+"\n✓ Done");else UI.toast(this,"Marked locally");});}else t.setText(r.get("title").getAsString()+"\n✓ Done");});}}
